function Add-PowerField($page,[int]$Index,$Def,[int]$Y){$items=@(Get-PowerArray);if($Index -ge $items.Count){return 0};$obj=$items[$Index];$field=[string]$Def.Field;$type=[string]$Def.Type;$w=[math]::Max(320,$page.ClientSize.Width-26);$labelW=132;$inputX=150;$inputW=[math]::Max(115,$w-$inputX-76);$lbl=[System.Windows.Forms.Label]::new();$lbl.Text=[string]$Def.Label;$lbl.Font=$script:FontSmall;$lbl.ForeColor=$script:Ink;$lbl.Location=[System.Drawing.Point]::new(10,$Y);$lbl.Size=[System.Drawing.Size]::new($labelW,38);$page.Controls.Add($lbl);$tag=[pscustomobject]@{Index=$Index;Field=$field};$ctrl=$null;$height=44
 if($type -eq 'Choice' -or $type -eq 'EditChoice'){$ctrl=[System.Windows.Forms.ComboBox]::new();$ctrl.DropDownStyle=if($type -eq 'EditChoice'){'DropDown'}else{'DropDownList'};[void]$ctrl.Items.AddRange([object[]]$Def.Options);$ctrl.Location=[System.Drawing.Point]::new($inputX,$Y-3);$ctrl.Width=$inputW;$ctrl.Font=$script:FontSmall;$ctrl.Tag=$tag;$ctrl.Add_SelectedIndexChanged({Power-Changed $this});if($type -eq 'EditChoice'){$ctrl.Add_TextChanged({Power-Changed $this})};$ctrl.Text=[string]$obj.$field}
 elseif($type -eq 'MultiChoice'){$ctrl=[System.Windows.Forms.Button]::new();$ctrl.Height=29;$ctrl.Location=[System.Drawing.Point]::new($inputX,$Y-3);$ctrl.Width=$inputW;$ctrl.Font=$script:FontSmall;$ctrl.Tag=$tag;$ctrl.FlatStyle='Flat';$ctrl.TextAlign='MiddleLeft';$val=[string]$obj.$field;$ctrl.Text=Get-MultiChoiceSummary $val;$menu=[System.Windows.Forms.ContextMenuStrip]::new();$menu.ShowCheckMargin=$true;foreach($opt in @($Def.Options)){$mi=[System.Windows.Forms.ToolStripMenuItem]::new();$mi.Text=[string]$opt;$mi.CheckOnClick=$true;$mi.Checked=@(Split-MultiChoiceValue $val)-contains [string]$opt;$mi.Tag=[pscustomobject]@{Index=$Index;Field=$field;Option=[string]$opt};$mi.Add_Click({$t=$this.Tag;Set-PowerMulti ([int]$t.Index) ([string]$t.Field) ([string]$t.Option) ([bool]$this.Checked)});[void]$menu.Items.Add($mi)};$ctrl.ContextMenuStrip=$menu;$ctrl.Add_Click({$this.ContextMenuStrip.Show($this,[System.Drawing.Point]::new(0,$this.Height))})}
 else{$ctrl=[System.Windows.Forms.TextBox]::new();$ctrl.Location=[System.Drawing.Point]::new($inputX,$Y-3);$ctrl.Width=$inputW;$ctrl.Font=$script:FontSmall;$ctrl.Tag=$tag;$ctrl.Text=[string]$obj.$field;if($type -eq 'Multi'){$ctrl.Multiline=$true;$ctrl.ScrollBars='Vertical';$ctrl.Height=62;$height=76};$ctrl.Add_TextChanged({Power-Changed $this})}
 $ctrl.BackColor=[System.Drawing.Color]::FromArgb(222,194,145);$ctrl.ForeColor=[System.Drawing.Color]::FromArgb(45,24,10);$ctrl.Anchor='Top,Left,Right';$page.Controls.Add($ctrl);$d=[System.Windows.Forms.Button]::new();$d.Text='🎲';$d.Tag=$tag;$d.Width=30;$d.Height=27;$d.Location=[System.Drawing.Point]::new($w-68,$Y-3);$d.Anchor='Top,Right';$d.FlatStyle='Flat';$d.Add_Click({Randomize-PowerField $this.Tag});$page.Controls.Add($d);return $height}
function Render-PowersSection($c,$leftHost,$rightHost){$head=[System.Windows.Forms.Button]::new();$head.Text=if($script:PowerFoldState){'[-]  Powers'}else{'[+]  Powers'};$head.Height=36;$head.Location=[System.Drawing.Point]::new(8,12);$head.Width=[math]::Max(190,$leftHost.ClientSize.Width-22);$head.Anchor='Top,Left,Right';$head.TextAlign='MiddleLeft';$head.Font=[System.Drawing.Font]::new('Georgia',9,[System.Drawing.FontStyle]::Bold);$head.FlatStyle='Flat';$head.BackColor=[System.Drawing.Color]::FromArgb(210,180,128);$head.ForeColor=[System.Drawing.Color]::FromArgb(45,24,10);$head.Add_Click({Toggle-PowerSection});$leftHost.Controls.Add($head);$rand=[System.Windows.Forms.Button]::new();$rand.Text='🎲 RANDOMIZE POWERS';$rand.BackColor=[System.Drawing.Color]::FromArgb(210,180,128);$rand.ForeColor=[System.Drawing.Color]::FromArgb(45,24,10);$rand.Height=34;$rand.Width=180;$rand.Location=[System.Drawing.Point]::new(8,58);$rand.Add_Click({Push-UndoState;$c=Get-CurrentCharacter;if($null -ne $c){$c.Fields['Powers']=Get-RandomPowerStructuredValue;Mark-CharacterChanged ([string]$c.Fields['Powers']);Render-CurrentCharacter}});$leftHost.Controls.Add($rand);if(-not $script:PowerFoldState){return};$items=@(Get-PowerArray);$y=104;for($i=0;$i -lt $items.Count;$i++){$k=[string]$i;$open=if($script:PowerEntryFoldState.ContainsKey($k)){[bool]$script:PowerEntryFoldState[$k]}else{$false};$b=[System.Windows.Forms.Button]::new();$nm=[string]$items[$i].PowerAbility;if([string]::IsNullOrWhiteSpace($nm)){$nm='Power '+($i+1)};$b.Text=if($open){'[-]  '+$nm}else{'[+]  '+$nm};$b.Tag=$i;$b.Height=32;$b.Location=[System.Drawing.Point]::new(8,$y);$b.Width=[math]::Max(190,$leftHost.ClientSize.Width-70);$b.Anchor='Top,Left,Right';$b.TextAlign='MiddleLeft';$b.Add_Click({Toggle-PowerEntry ([int]$this.Tag)});$leftHost.Controls.Add($b);$rm=[System.Windows.Forms.Button]::new();$rm.Text='X';$rm.Tag=$i;$rm.Width=34;$rm.Height=32;$rm.Location=[System.Drawing.Point]::new([math]::Max(200,$leftHost.ClientSize.Width-54),$y);$rm.Anchor='Top,Right';$rm.Add_Click({Push-UndoState;$a=@(Get-PowerArray);$idx=[int]$this.Tag;$n=@();for($j=0;$j -lt $a.Count;$j++){if($j -ne $idx){$n+=,$a[$j]}};Set-PowerArray $n;Render-CurrentCharacter});$leftHost.Controls.Add($rm);$y+=38;if($open){foreach($d in @(Get-PowerFields)){$h=Add-PowerField $leftHost $i $d $y;$y+=$h};$y+=8}};$add=[System.Windows.Forms.Button]::new();$add.Text='+ ADD POWER';$add.Width=150;$add.Height=32;$add.Location=[System.Drawing.Point]::new(8,$y);$add.Add_Click({Push-UndoState;$a=@(Get-PowerArray);$a+=,(New-PowerEntry);Set-PowerArray $a;Render-CurrentCharacter});$leftHost.Controls.Add($add);$hint=[System.Windows.Forms.Label]::new();$hint.Text='Powers are repeatable. Each ability keeps its own type, strength, control, limitations, weaknesses, source, visibility, and notes.';$hint.AutoSize=$false;$hint.Size=[System.Drawing.Size]::new([math]::Max(220,$rightHost.ClientSize.Width-24),120);$hint.Location=[System.Drawing.Point]::new(10,14);$hint.Font=$script:FontSmall;$hint.ForeColor=$script:Muted;$rightHost.Controls.Add($hint)}

